 if(p==='ICT 2022 Mentorship Model')n=90;
 else if(p==='Silver Bullet')n=85;
 else if(p==='Power of 3 (PO3)')n=80;
 else if(p==='NY Judas Swing')n=75;
 else if(p==='3 Drives Pattern')n=70;
 else if(p==='SMT')n=68;
